// lib/collection/src/grouping/aggregator.rs:15-43 — THE UNCHECKED MULTIPLICATION (constructor runs before any search)
pub(super) struct GroupsAggregator {
    groups: AHashMap<GroupId, Hits>,
    max_group_size: usize,
    grouped_by: JsonPath,
    max_groups: usize,
    full_groups: AHashSet<GroupId>,
    group_best_scores: AHashMap<GroupId, ScoredPoint>,
    all_ids: AHashSet<ExtendedPointId>,
    order: Option<Order>,
}
impl GroupsAggregator {
    pub(super) fn new(groups: usize, group_size: usize, grouped_by: JsonPath, order: Option<Order>) -> Self {
        Self {
            groups: AHashMap::with_capacity(groups),
            max_group_size: group_size,
            grouped_by,
            max_groups: groups,
            full_groups: AHashSet::with_capacity(groups),
            group_best_scores: AHashMap::with_capacity(groups),
            all_ids: AHashSet::with_capacity(groups * group_size),   // <<< 1e6 * 1e6 = 1e12 capacity eagerly reserved
            order,
        }
    }
// (ExtendedPointId is a 24-byte enum, lib/segment/src/types.rs:169; hashbrown rounds 1e12 capacity up to 2^40 buckets
